<?php require __DIR__.'/../bootstrap.php';require_login();$s=db()->prepare("SELECT t.*,p.name project_name FROM tasks t LEFT JOIN projects p ON p.id=t.project_id WHERE t.user_id=? ORDER BY t.created_at DESC");$s->execute([current_user()['id']]);$ts=$s->fetchAll();$title='Tasks';require __DIR__.'/../includes/header.php';?><div class="page-head"><h1><?=e(ui_label("tasks","Tasks"))?></h1><a class="btn" href="/tasks/create/">+ New Task</a></div><div class="kanban"><?php foreach(['Todo','In Progress','Completed'] as $st):?><section class="kanban-col"><h3><?=e($st)?></h3><?php foreach(array_filter($ts,fn($x)=>$x['status']===$st) as $t):?><article class="card task setting-target" id="task-<?=$t['id']?>"><span class="priority <?=strtolower($t['priority'])?>"><?=e($t['priority'])?></span><h3><?=e($t['title'])?></h3><p><?=e($t['description'])?></p><small><?=e($t['project_name']??'No project')?></small><a href="/tasks/edit/?id=<?=$t['id']?>" class="edit-btn">Edit</a></article><?php endforeach;?></section><?php endforeach;?></div><?php require __DIR__.'/../includes/footer.php'; ?>